public static int getExperienceForLevel(int level) {
        if (level == 0) {
            return 0;
        }

        if (level > 0 && level < 17) {
            return level * level + 6 * level;
        } else if (level > 16 && level < 32) {
            return (int) (2.5 * level * level - 40.5 * level + 360);
        } else {
            return (int) (4.5 * level * level - 162.5 * level + 2220);
        }
    }

